kam_report_config:
{
  "reportType": "INTERNAL_PERF_RR_DISPLAY",
  "externalReportType": "RR_DISPLAY_REPORT",
  "visibility": "INTERNAL_PERFORMANCE",
  "filterTags": [
    "report_group:rr",
    "report_group:search_query"
  ],
  "externalRequiredFilters": [],
  "description": "Display ad request / response volume and response rate for a marketplace over a period, grouped by any combination of the dimensions below: supply network, page type, device, ad unit, product category (L1-L3), hour of day, or the keyword the request carried. Replaces the six single-grain Display RR reports. Group by page_type for page-type RR, by hour for the hourly RR curve, by ad_unit to find ad units with zero responses, by keyword for keyword-level Display RR, or by keyword + ad_unit for the follow-up breakdown. Pass a NOT IN ('', 'NA') filter on the grouping column to reproduce the null/blank guards the retired reports hardcoded.",
  "source": "GOOGLE_BIG_QUERY",
  "sourceInfo": {
    "appKey": "GCP_BQ_KAM_CREDENTIALS"
  },
  "cacheInfo": {
    "isCachingEnabled": true,
    "cachingExpiryInSec": 900
  },
  "attributes": {
    "network": {
      "key": "network",
      "selector": "r.network",
      "type": "STRING",
      "externalColumnName": "network",
      "description": "The supply network / channel the ad request came from.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "page_type": {
      "key": "page_type",
      "selector": "r.page_type",
      "type": "STRING",
      "externalColumnName": "page_type",
      "description": "Page type the Display ad request was served on. Filter page_type NOT IN ('', 'NA') to drop unattributed rows.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "device": {
      "key": "device",
      "selector": "r.device",
      "type": "STRING",
      "externalColumnName": "device",
      "description": "The device type the ad request came from (mobile, desktop, app, ...).",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "ad_unit": {
      "key": "ad_unit",
      "selector": "r.ad_unit",
      "type": "STRING",
      "externalColumnName": "ad_unit",
      "description": "The display ad unit / placement slot the request was attributed to.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "category_l1": {
      "key": "category_l1",
      "selector": "r.category_l1",
      "type": "STRING",
      "externalColumnName": "category_l1",
      "description": "Top-level (L1) product category the requests/responses were attributed to.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "category_l2": {
      "key": "category_l2",
      "selector": "r.category_l2",
      "type": "STRING",
      "externalColumnName": "category_l2",
      "description": "Second-level (L2) product category.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "category_l3": {
      "key": "category_l3",
      "selector": "r.category_l3",
      "type": "STRING",
      "externalColumnName": "category_l3",
      "description": "Third-level (L3) product category.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "hour": {
      "selector": "EXTRACT(HOUR FROM r.date_hour)",
      "type": "INTEGER",
      "description": "Hour of day (0-23) the Display ad request was made, from date_hour. Group by this to find low-activity hours dragging RR down.",
      "key": "hour",
      "externalColumnName": "hour",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "keyword": {
      "selector": "LOWER(TRIM(r.filter_keywords))",
      "type": "STRING",
      "description": "Keyword the Display ad request carried (filter_keywords), lowercased and trimmed. Filter keyword NOT IN ('') to drop requests with no keyword.",
      "key": "keyword",
      "externalColumnName": "keyword",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    }
  },
  "metrics": {
    "requests": {
      "key": "requests",
      "selector": "COALESCE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.requests ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "requests",
      "description": "Ad requests received for this dimension grouping.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "responses": {
      "key": "responses",
      "selector": "COALESCE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.responses ELSE 0 END), 0)",
      "type": "FLOAT",
      "externalColumnName": "responses",
      "description": "Requests that returned at least one ad (responses) for this dimension grouping.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    },
    "response_rate": {
      "key": "response_rate",
      "selector": "SAFE_DIVIDE(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.responses ELSE 0 END) * 100, NULLIF(SUM(CASE WHEN r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' THEN r.requests ELSE 0 END), 0))",
      "type": "FLOAT",
      "externalColumnName": "response_rate",
      "description": "Response rate (%) = responses / requests * 100 for this dimension grouping.",
      "filterTags": [
        "report_group:rr",
        "report_group:search_query"
      ]
    }
  },
  "dateRanges": {
    "count": 1,
    "dataAvailabilityDays": 90,
    "maxDataFetchDaysDuration": 31
  },
  "query": {
    "REPORTING": "SELECT __ATTRIBUTES__, __METRICS__ FROM `prj-onlinesales-prod-01.reporting.os_display_ads_filtered_level_performance_facts` AS r JOIN `prj-onlinesales-prod-01.reporting.marketplace_clients` AS mc ON r.marketplace_client_id = mc.marketplace_client_id WHERE mc.agency_id = '__AGENCY_ID__' AND r.date BETWEEN '__START_DATE_1__' AND '__END_DATE_1__' AND __FILTER__ GROUP BY __ATTRIBUTES_GROUP_BY__;",
    "MERCHANT": "",
    "GROUPED": ""
  },
  "application": "irisTestApplication"
}
